    ("wc count", "`wc -l` counts lines, `-w` words, `-c` bytes; `grep -c` counts matches — pipe, don't parse visually."),
    ("tee split output", "`cmd | tee out.log` shows AND saves; `-a` appends — the honest way to keep terminal evidence."),
    ("logger syslog", "`logger -t myapp 'ready'` writes syslog with a tag; `-p local0.err` routes severity for aggregators."),
    ("head tail files", "`head -20` previews starts, `tail -30 -f` follows ends; combine with pipes instead of opening editors."),
    ("cut fields", "`cut -d: -f1 /etc/passwd` extracts columns; `-c1-3` slices characters — quick parsing without awk."),
    ("tr translate", "`tr 'a-z' 'A-Z'` uppercases streams; `-d` deletes chars, `-s` squeezes repeats in pipelines."),
    ("paste join lines", "`paste -d, a b` zips lines side by side; `-s` serializes one file into a single line."),
    ("comm compare sorted", "`comm -23 a b` lines unique to a (sorted inputs required); `diff` for context, `comm` for sets."),
    ("column -t align", "`column -t` aligns whitespace tables readably; `-s,` sets delimiters for CSV-ish previews."),
    ("expand unexpand tabs", "`expand -t 4` converts tabs to spaces for consistency; `unexpand` reverses when tools demand tabs."),
    ("tac reverse cat", "`tac` prints lines last-first (logs newest-last files); `rev` reverses characters per line."),
    ("nl number lines", "`nl -ba` numbers all lines for reference; `-v10` starts counting at ten for excerpts."),
    ("shuf random lines", "`shuf file` randomizes (sampling, shuffling tests); `-n5` picks five random lines for spot checks."),
    ("split large files", "`split -l 1000 big.csv part_` chunks by lines (`-b 100M` by bytes); `cat part_*` reassembles."),
    ("csplit context split", "`csplit file '/^==/' '{*}'` splits on regex matches — one file per section for reports."),
    ("strings binaries", "`strings app.bin | grep -i version` extracts readable text from binaries for quick forensics."),
    ("od hexdump bytes", "`od -A x -t x1z file` hexdumps with ASCII sidecar; `xxd` is friendlier when installed."),
