    ("reversed sorted", "`reversed()` iterates backward lazily; `sorted()` returns new lists (use `.sort()` to mutate in place)."),
    ("min max key", "`min(users, key=lambda u: u.age)` finds extrema by criterion; `default=` guards empty inputs."),
    ("round() decimals", "`round(2.675, 2)` surprises (binary floats) — money wants Decimal, display wants formatting, not floats."),
    ("input strip validate", "`input().strip()` trims; convert in try/except (`int()`) — every prompt is hostile input until proven."),
    ("open errors", "`open(f, errors='replace')` survives mojibake logs; default strict raises — choose deliberately per source."),
    ("json indent sort", "`json.dumps(d, indent=2, sort_keys=True)` diffs cleanly in git; `separators` compacts wire payloads."),
    ("argparse choices", "`choices=[...]` validates CLI input free with usage errors; `required=True` marks must-haves."),
    ("logging levels", "DEBUG < INFO < WARNING < ERROR < CRITICAL; set root once, per-module loggers inherit — prints can't do this."),
