    ("verbatim module syntax", "Keeps `import type` elisions explicit so emitted JS never accidentally imports erased types at runtime."),
    ("isolatedModules", "Each file must transpile standalone (no const-enum cross-file, no re-export ambiguity) — required by esbuild/swc."),
    ("rewriteRelativeImportExtensions", "Rewrites `./x.js` to `./x.ts` automatically for source-accurate imports under nodenext resolution."),
    ("noUncheckedSideEffectImports", "Flags side-effect imports lacking attribution — tree-shaking honesty for CSS/polyfill imports."),
    ("exactOptionalPropertyTypes deep", "Pairs with nested Partial patterns for API patch types where absent ≠ explicit-undefined matters."),
