    ("--inspect debug", "`node --inspect` exposes Chrome DevTools debugging (breakpoints, heap snapshots); `--inspect-brk` pauses on entry."),
    ("--experimental-strip-types", "New Node runs TypeScript directly by stripping types (no enums/namespaces); tsx/ts-node still rule complex setups."),
    ("package exports map", "`exports` in package.json gates subpath imports (`pkg/feature`) and hides internals — dual CJS/ESM via conditions."),
    ("engines field", "`engines: {node: '>=20'}` documents runtime needs (npm warns, doesn't enforce); `.nvmrc` + Docker pin the reality."),
    ("npm ci cache clean", "`npm ci` for reproducible installs; `npm cache clean --force` and `node_modules` nukes fix haunted dependency states."),
    ("npm outdated update", "`npm outdated` lists drift; `npm update` bumps semver-compatible; majors need explicit `install pkg@2` + migration."),
    ("npm audit fix", "`npm audit` grades vulnerabilities; `npm audit fix` patches compatible ones — review majors, they break APIs."),
    ("package-lock review", "Review lockfile diffs in PRs (new deps, registry URLs); lockfile poisoning is a real supply-chain vector."),
    ("npm workspaces", "Workspaces (`packages/*`) share one lockfile across monorepo packages with cross-links; `npm run -w pkg` targets one."),
    ("npx dlx", "`npx`/`npm dlx` runs packages without installing (scaffolds, one-off CLIs); pins versions to avoid moving-target surprises."),
    ("corepack yarn pnpm", "Corepack shims yarn/pnpm per `packageManager` field; pnpm's store saves gigabytes across projects vs npm duplicates."),
    ("SIGINT SIGTERM handlers", "Handle both (Ctrl-C vs orchestrators); cleanup async work before `process.exit`, and never swallow the second signal."),
    ("process.title ps", "`process.title` renames the process in `ps`/`top` (`myapp: worker`) — operability for multi-process boxes."),
    ("NODE_PATH avoid", "`NODE_PATH` global resolution breaks portability — bundle deps locally; only legacy migrations need it temporarily."),
    ("--max-old-space", "`--max-old-space-size=8192` raises heap before OOM exits; pair with heap snapshots to fix the leak, not just the ceiling."),
    ("--trace-warnings", "`--trace-warnings` prints stacks for deprecations/unhandled rejections — turns warnings into actionable locations."),
    ("--pending-deprecation", "Opt into future breaking behaviors early (`--pending-deprecation`) to migrate before forced upgrades."),
    ("--trace-uncaught", "Uncaught exceptions print full context with `--trace-uncaught`; combine with domain logging in production."),
    ("worker execArgv", "Workers inherit `execArgv` unless overridden — pass `--inspect` ports explicitly to debug specific workers."),
    ("resourceLimits", "`new Worker(path, { resourceLimits: { maxOldGenerationSizeMb: 512 } })` caps rogue workers per thread."),
