    ("\\d+ details", "`\\d+ tabel` adds size/descriptions to structure output; `\\dt+` sizes all tables for capacity reviews."),
    ("\\l+ sizes", "`\\l+` shows database sizes on disk — growth anomalies surface here before disks fill."),
    ("\\conninfo", "`\\conninfo` prints user/db/host/port/SSL state of the live session — verify before destructive work."),
